self.addEventListener('install', event => event.waitUntil(self.skipWaiting()));
self.addEventListener('activate', event => event.waitUntil((async () => {
  const names = await caches.keys();
  await Promise.all(names.filter(name => name.startsWith('chirpy-')).map(name => caches.delete(name)));
  await self.clients.claim();
  const windows = await self.clients.matchAll({ type: 'window' });
  await self.registration.unregister();
  // Retiring a worker alone leaves its open documents using stale HTML/assets.
  // The new worker has no fetch handler, so these navigations go to the network.
  await Promise.all(windows.map(client => client.navigate(client.url).catch(() => {})));
})()));
